using System;using System.Drawing;using System.Linq;using System.Windows.Forms;using System.IO;
namespace IDSketcher {
// UI layouts are authored at 96 DPI and scaled explicitly for each monitor.
// Canvas geometry stays in document pixels; Windows does not bitmap-stretch UI text.
static class DisplayLayout {
 public static void CentreDialog(Form dialog,Form owner){var area=Screen.FromControl(owner??dialog).WorkingArea;var anchor=owner==null?area:owner.Bounds;int x=anchor.Left+(anchor.Width-dialog.Width)/2,y=anchor.Top+(anchor.Height-dialog.Height)/2;dialog.Location=new Point(Math.Max(area.Left,Math.Min(x,area.Right-dialog.Width)),Math.Max(area.Top,Math.Min(y,area.Bottom-dialog.Height)));}
 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern IntPtr SetThreadDpiAwarenessContext(IntPtr context);
 public static void InitializeScaling(){try{SetThreadDpiAwarenessContext(new IntPtr(-4));}catch(EntryPointNotFoundException){/* Standard Windows scaling on older systems. */}}

 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern IntPtr GetThreadDpiAwarenessContext();
 [System.Runtime.InteropServices.DllImport("user32.dll")] static extern bool AreDpiAwarenessContextsEqual(IntPtr a,IntPtr b);
 public static string ScalingDescription(){var c=GetThreadDpiAwarenessContext();return "Context="+c.ToInt64()+" matches="+string.Join(",",Enumerable.Range(1,5).Where(i=>AreDpiAwarenessContextsEqual(c,new IntPtr(-i))).Select(i=>(-i).ToString()).ToArray());}
 public static void CheckScalingManifest(){try{if(!AreDpiAwarenessContextsEqual(GetThreadDpiAwarenessContext(),new IntPtr(-4)))throw new Exception("Per-monitor DPI awareness not active: "+ScalingDescription());}catch(EntryPointNotFoundException){/* Older Windows uses standard DPI virtualization. */}}

 public static void FitDialog(Form form,Rectangle workingArea){Size content=form.ClientSize;Size frame=new Size(form.Width-content.Width,form.Height-content.Height);int width=Math.Max(240,workingArea.Width-24-frame.Width),height=Math.Max(180,workingArea.Height-24-frame.Height);if(content.Width<=width&&content.Height<=height)return;form.AutoScroll=true;form.AutoScrollMinSize=content;form.ClientSize=new Size(Math.Min(content.Width,width),Math.Min(content.Height,height));form.Location=new Point(workingArea.Left+(workingArea.Width-form.Width)/2,workingArea.Top+(workingArea.Height-form.Height)/2);}
 public static int ToolbarHeight(FlowLayoutPanel bar){int available=Math.Max(1,bar.ClientSize.Width-bar.Padding.Horizontal),x=0,row=0,height=bar.Padding.Vertical;foreach(Control control in bar.Controls){if(!control.Visible)continue;int width=control.Width+control.Margin.Horizontal,h=control.Height+control.Margin.Vertical;if(x>0&&x+width>available){height+=row;row=0;x=0;}x+=width;row=Math.Max(row,h);}return height+row;}
}
partial class Studio {
 FlowLayoutPanel responsiveToolbar;Panel paletteHost,colourSection,symmetrySection,layerSection;TabControl paletteTabs;TabPage colourPage,layerPage,symmetryPage;bool updatingDisplay,compactPalette;
 void ConfigureDisplayLayout(FlowLayoutPanel toolbar,Panel right,Panel colour,Panel symmetry,Panel layer){responsiveToolbar=toolbar;paletteHost=right;colourSection=colour;symmetrySection=symmetry;layerSection=layer;paletteTabs=new TabControl{Dock=DockStyle.Fill};colourPage=new TabPage("Colour"){AutoScroll=true,Padding=new Padding(5)};layerPage=new TabPage("Layers"){Padding=new Padding(5)};symmetryPage=new TabPage("Symmetry"){AutoScroll=true,Padding=new Padding(5)};paletteTabs.TabPages.AddRange(new[]{colourPage,layerPage,symmetryPage});toolbar.Layout+=delegate{UpdateDisplayLayout();};Resize+=delegate{UpdateDisplayLayout();};Shown+=delegate{UpdateDisplayLayout();};UpdateDisplayLayout();}
 void UpdateDisplayLayout(){if(SharpDpi.IsScaling(this)||updatingDisplay||responsiveToolbar==null)return;updatingDisplay=true;try{int height=DisplayLayout.ToolbarHeight(responsiveToolbar);if(responsiveToolbar.Height!=height)responsiveToolbar.Height=height;bool compact=ClientSize.Height-responsiveToolbar.Height-status.Height<SharpDpi.Px(this,800);if(compact!=compactPalette){paletteHost.SuspendLayout();paletteHost.Padding=compact?new Padding(SharpDpi.Px(this,8)):new Padding(SharpDpi.Px(this,16),SharpDpi.Px(this,8),SharpDpi.Px(this,16),SharpDpi.Px(this,8));if(compact){paletteHost.Controls.Remove(colourSection);paletteHost.Controls.Remove(symmetrySection);paletteHost.Controls.Remove(layerSection);colourSection.Dock=DockStyle.Top;colourSection.Height=SharpDpi.Px(this,fillRowShown?576:460);colourPage.Controls.Add(colourSection);symmetrySection.Dock=DockStyle.Top;symmetrySection.Height=SharpDpi.Px(this,112);symmetryPage.Controls.Add(symmetrySection);layerSection.Dock=DockStyle.Fill;layerPage.Controls.Add(layerSection);paletteHost.Controls.Add(paletteTabs);}else{colourPage.Controls.Remove(colourSection);symmetryPage.Controls.Remove(symmetrySection);layerPage.Controls.Remove(layerSection);paletteHost.Controls.Remove(paletteTabs);layerSection.Dock=DockStyle.Fill;symmetrySection.Dock=DockStyle.Top;colourSection.Dock=DockStyle.Top;paletteHost.Controls.Add(layerSection);paletteHost.Controls.Add(symmetrySection);paletteHost.Controls.Add(colourSection);}compactPalette=compact;Theme.Apply(paletteHost);swatch.BackColor=canvas.Ink;paletteHost.ResumeLayout(true);}responsiveToolbar.PerformLayout();}finally{updatingDisplay=false;}}
 void DisposeDisplayLayout(){if(paletteTabs!=null&&paletteTabs.Parent==null)paletteTabs.Dispose();}
 public void TestDisplayLayout(){DisplayLayout.CheckScalingManifest();WindowState=FormWindowState.Normal;foreach(var size in new[]{new Size(1920,1000),new Size(1536,800),new Size(1280,640),new Size(1024,540),new Size(1920,1000)}){ClientSize=size;PerformLayout();UpdateDisplayLayout();responsiveToolbar.PerformLayout();foreach(Control item in responsiveToolbar.Controls)if(item.Visible&&(item.Right>responsiveToolbar.ClientSize.Width||item.Bottom>responsiveToolbar.ClientSize.Height))throw new Exception("Toolbar clipped at "+size+": "+item.Text);if(canvas.Width<450||canvas.Height<300)throw new Exception("Canvas too small at "+size);if(size.Height<900){if(!compactPalette||paletteTabs.Parent!=paletteHost)throw new Exception("Compact palette missing");paletteTabs.SelectedTab=layerPage;layerPage.PerformLayout();layerSection.PerformLayout();if(layers.Height<150)throw new Exception("Layer list clipped at "+size);paletteTabs.SelectedTab=colourPage;colourPage.PerformLayout();if(colourSection.Width<240)throw new Exception("Colour controls clipped");}else if(compactPalette)throw new Exception("Full palette not restored");}
 using(var dialog=new Setup()){DisplayLayout.FitDialog(dialog,new Rectangle(0,0,1280,640));if(dialog.Height>616||!dialog.AutoScroll||dialog.AutoScrollMinSize.Height<630)throw new Exception("Small-screen setup scrolling");}
 ClientSize=new Size(1280,800);UpdateDisplayLayout();dirty=false;}
 public void PreviewDisplayLayout(){WindowState=FormWindowState.Normal;ClientSize=new Size(1280,640);PerformLayout();UpdateDisplayLayout();paletteTabs.SelectedTab=colourPage;using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"compact-colour-preview.png"));}paletteTabs.SelectedTab=layerPage;using(var b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"compact-layers-preview.png"));}}
}
}
